+                @Override
+                public org.elasticsearch.compute.data.Block eval(Page page) {
+                    // This is a pass-through evaluator, since it sits directly on the source loading (no prior expressions)
+                    return page.getBlock(0);
+                }
+
+                @Override
+                public void close() {}
+            }).get(driverContext1)
+        );
