+            SemanticTextField.getChunksFieldName(filteredKnnVectorQueryBuilder.getFieldName()),
+            buildNewKnnVectorQuery(
+                SemanticTextField.getEmbeddingsFieldName(filteredKnnVectorQueryBuilder.getFieldName()),
